import type { Metadata } from "next";
import type { ReactNode } from "react";
import "./globals.css";

export const metadata: Metadata = {
  title: "LSV Operational Service Summary",
  robots: { index: false, follow: false },
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en-AU">
      <body>{children}</body>
    </html>
  );
}

:root {
  --lsv-blue: #1d4ed8;
  --lsv-navy: #0f2a5f;
  --text: #1f2937;
  --muted: #6b7280;
  --border: #e5e7eb;
  --danger: #b91c1c;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--text);
  background: #f3f4f6;
  min-height: 100vh;
}
.auth-shell {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.auth-card {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 28px 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 1px 2px rgba(0,0,0,0.04);
}
.auth-card h1 { font-size: 20px; margin: 0 0 4px; color: var(--lsv-navy); }
.auth-card p.sub { margin: 0 0 20px; color: var(--muted); font-size: 14px; }
.auth-card label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; }
.auth-card input {
  width: 100%; padding: 10px 12px; font-size: 16px; border: 1px solid #cbd5e1; border-radius: 6px;
}
.auth-card input.code { text-align: center; font-size: 26px; letter-spacing: 0.4em; font-family: ui-monospace, monospace; }
.auth-card button.primary {
  width: 100%; margin-top: 14px; padding: 11px; font-size: 15px; font-weight: 600; color: #fff;
  background: var(--lsv-blue); border: 0; border-radius: 6px; cursor: pointer;
}
.auth-card button.primary:disabled { opacity: 0.6; cursor: default; }
.auth-card button.link {
  background: none; border: 0; color: var(--muted); font-size: 13px; cursor: pointer; text-decoration: underline; padding: 0; margin-top: 14px;
}
.auth-card .error { color: var(--danger); font-size: 14px; margin-top: 12px; }
.auth-card .hint { color: var(--muted); font-size: 12px; margin-top: 12px; text-align: center; }
.auth-card .sent { text-align: center; padding: 8px 0; }
.auth-card .sent .icon { font-size: 34px; }
.auth-card .row { display: flex; gap: 8px; justify-content: center; margin-top: 12px; }
.spinner {
  width: 28px; height: 28px; margin: 0 auto 10px; border-radius: 50%;
  border: 3px solid var(--lsv-blue); border-top-color: transparent; animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

import { Suspense } from "react";
import { redirect } from "next/navigation";
import { getAuthUser } from "@/lib/auth";
import { resendConfigured } from "@/env";
import { SignInForm } from "./sign-in-form";

export const dynamic = "force-dynamic";

export default async function SignInPage() {
  const user = await getAuthUser();
  if (user) redirect("/");
  return (
    <main className="auth-shell">
      <Suspense>
        <SignInForm codeSignInAvailable={resendConfigured()} />
      </Suspense>
    </main>
  );
}

"use client";

import { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { safeRedirect } from "@/lib/safe-redirect";

const BASE = process.env.NEXT_PUBLIC_BASE_PATH ?? "";

async function errorFromResponse(res: Response, fallback: string): Promise<Error> {
  const data = await res.json().catch(() => null);
  return new Error(data?.error ?? fallback);
}

/**
 * Sign-in form ported from AccessBuddy: email magic link by default, with
 * the 6-digit code path available when a mail provider is configured.
 */
export function SignInForm({ codeSignInAvailable }: { codeSignInAvailable: boolean }) {
  const router = useRouter();
  const params = useSearchParams();
  const redirectTo = safeRedirect(params.get("redirect"));
  const [email, setEmail] = useState("");
  const [mode, setMode] = useState<"link" | "code">("link");
  const [sent, setSent] = useState(false);
  const [code, setCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [resent, setResent] = useState(false);

  async function sendLink() {
    const res = await fetch(`${BASE}/api/auth/send-magic-link`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: email.trim(), redirect: redirectTo }),
    });
    if (!res.ok) throw await errorFromResponse(res, "Failed to send sign-in link");
    const data = await res.json();
    if (data.clientSend) {
      // Firebase sends the email itself when Resend is not configured.
      const { auth } = await import("@/lib/firebase-client");
      const { sendSignInLinkToEmail } = await import("firebase/auth");
      await sendSignInLinkToEmail(auth, email.trim(), {
        url: `${window.location.origin}${BASE}/auth/callback?redirect=${encodeURIComponent(redirectTo)}`,
        handleCodeInApp: true,
      });
    }
    window.localStorage.setItem("emailForSignIn", email.trim());
  }

  async function sendCode() {
    const res = await fetch(`${BASE}/api/auth/send-otp`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: email.trim() }),
    });
    if (!res.ok) throw await errorFromResponse(res, "Failed to send code");
  }

  async function handleSend() {
    if (!email.trim()) return;
    setLoading(true);
    setError(null);
    try {
      if (mode === "code") await sendCode();
      else await sendLink();
      setSent(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  async function handleResend() {
    setLoading(true);
    setError(null);
    try {
      if (mode === "code") await sendCode();
      else await sendLink();
      setResent(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to resend.");
    } finally {
      setLoading(false);
    }
  }

  async function handleVerifyCode() {
    if (code.length !== 6) return;
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`${BASE}/api/auth/verify-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim(), code }),
      });
      if (!res.ok) throw await errorFromResponse(res, "Invalid code");
      router.push(redirectTo);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Verification failed");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="auth-card">
      <h1>Operational Service Summary</h1>
      <p className="sub">Life Saving Victoria. Sign in with your email, no password needed.</p>
      {!sent ? (
        <>
          <label htmlFor="email">Email address</label>
          <input
            id="email"
            type="email"
            autoComplete="email"
            autoFocus
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSend()}
            placeholder="you@example.com"
          />
          <button className="primary" onClick={handleSend} disabled={loading || !email.trim()}>
            {loading ? "Sending..." : mode === "code" ? "Send sign-in code" : "Send sign-in link"}
          </button>
          {error && <p className="error">{error}</p>}
          <p className="hint">
            {mode === "code" ? "We will email you a 6-digit code." : "We will email you a sign-in link."}
          </p>
          {codeSignInAvailable && (
            <div className="row">
              <button className="link" onClick={() => setMode(mode === "code" ? "link" : "code")}>
                {mode === "code" ? "Use a sign-in link instead" : "Use a 6-digit code instead"}
              </button>
            </div>
          )}
        </>
      ) : mode === "code" ? (
        <div className="sent">
          <div className="icon">✉</div>
          <p>Enter the 6-digit code we sent to <strong>{email}</strong></p>
          <input
            className="code"
            inputMode="numeric"
            pattern="[0-9]*"
            maxLength={6}
            placeholder="000000"
            autoFocus
            value={code}
            onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
            onKeyDown={(e) => e.key === "Enter" && handleVerifyCode()}
          />
          <button className="primary" onClick={handleVerifyCode} disabled={loading || code.length !== 6}>
            {loading ? "Verifying..." : "Sign in"}
          </button>
          {error && <p className="error">{error}</p>}
          <div className="row">
            <button className="link" onClick={handleResend} disabled={loading}>{resent ? "Code resent" : "Resend code"}</button>
            <button className="link" onClick={() => { setSent(false); setCode(""); setError(null); }}>Use a different email</button>
          </div>
        </div>
      ) : (
        <div className="sent">
          <div className="icon">✉</div>
          <p><strong>Check your email</strong></p>
          <p className="hint">We sent a sign-in link to <strong>{email}</strong>. Open it in this browser.</p>
          {resent && <p className="hint">Link resent.</p>}
          {error && <p className="error">{error}</p>}
          <div className="row">
            <button className="link" onClick={handleResend} disabled={loading}>Resend link</button>
            <button className="link" onClick={() => { setSent(false); setResent(false); setError(null); }}>Use a different email</button>
          </div>
        </div>
      )}
    </div>
  );
}

import { Suspense } from "react";
import { AuthCallback } from "./auth-callback";

export const dynamic = "force-dynamic";

export default function AuthCallbackPage() {
  return (
    <main className="auth-shell">
      <Suspense>
        <AuthCallback />
      </Suspense>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { safeRedirect } from "@/lib/safe-redirect";

const BASE = process.env.NEXT_PUBLIC_BASE_PATH ?? "";

/**
 * Completes the magic-link sign-in: Firebase verifies the link, the ID token
 * is exchanged for the httpOnly session cookie at /api/auth/session, and the
 * token is refreshed so the `member` claim reaches Firestore rules.
 */
export function AuthCallback() {
  const router = useRouter();
  const params = useSearchParams();
  const redirectTo = safeRedirect(params.get("redirect"));
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function complete() {
      try {
        const { auth } = await import("@/lib/firebase-client");
        const { isSignInWithEmailLink, signInWithEmailLink } = await import("firebase/auth");
        if (!isSignInWithEmailLink(auth, window.location.href)) {
          setError("Invalid sign-in link.");
          return;
        }
        let email = window.localStorage.getItem("emailForSignIn");
        if (!email) email = window.prompt("Please enter your email to confirm sign-in:");
        if (!email) {
          setError("Email required to complete sign-in.");
          return;
        }
        const result = await signInWithEmailLink(auth, email, window.location.href);
        window.localStorage.removeItem("emailForSignIn");
        const idToken = await result.user.getIdToken();
        const res = await fetch(`${BASE}/api/auth/session`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ idToken }),
        });
        if (res.status === 403) {
          await auth.signOut();
          router.replace("/not-a-member");
          return;
        }
        if (!res.ok) throw new Error("Failed to create session");
        await result.user.getIdToken(true);
        router.replace(redirectTo);
      } catch (err) {
        console.error("Auth callback error:", err);
        setError("Sign-in failed. The link may have expired. Please try again.");
      }
    }
    complete();
  }, [router, redirectTo]);

  return (
    <div className="auth-card">
      {error ? (
        <div className="sent">
          <p className="error">{error}</p>
          <a href={`${BASE}/sign-in`}>Back to sign-in</a>
        </div>
      ) : (
        <div className="sent">
          <div className="spinner" />
          <p className="hint">Completing sign-in...</p>
        </div>
      )}
    </div>
  );
}

const BASE = process.env.NEXT_PUBLIC_BASE_PATH ?? "";

export default function NotAMemberPage() {
  return (
    <main className="auth-shell">
      <div className="auth-card sent">
        <h1>Not on the member list</h1>
        <p className="hint">
          Your email signed in, but it is not on the Operational Service Summary member list. Ask the
          State Lifesaving Communications Officer to add you, then sign in again.
        </p>
        <p><a href={`${BASE}/sign-in`}>Back to sign-in</a></p>
      </div>
    </main>
  );
}

import { NextResponse, type NextRequest } from "next/server";
import { cookies } from "next/headers";
import { SESSION_COOKIE_NAME } from "@/lib/auth";
import { clientEnv } from "@/env";

export const dynamic = "force-dynamic";

/**
 * Plain-link logout for the page's "Or log out" anchor (window.OSS_LOGOUT_URL).
 * Clears the session cookie and lands on sign-in. The bridge script also
 * signs the Firebase client out before following this link.
 */
export async function GET(_request: NextRequest) {
  const store = await cookies();
  store.delete(SESSION_COOKIE_NAME);
  return NextResponse.redirect(`${clientEnv.NEXT_PUBLIC_APP_URL}${clientEnv.NEXT_PUBLIC_BASE_PATH}/sign-in`, { status: 303 });
}

import { NextResponse } from "next/server";
import { clientEnv } from "@/env";

export const dynamic = "force-dynamic";

export function GET() {
  return NextResponse.json({ ok: true, version: clientEnv.NEXT_PUBLIC_APP_VERSION, time: new Date().toISOString() });
}

import { NextRequest, NextResponse } from "next/server";
import { cookies } from "next/headers";
import { getAdminAuth } from "@/lib/firebase-admin";
import { SESSION_COOKIE_NAME, SESSION_MAX_AGE_SECONDS, sessionCookieOptions } from "@/lib/auth";
import { getMemberByEmail, linkMemberUid } from "@/lib/members";
import { checkRateLimit, getClientIp } from "@/lib/rate-limit";

export const dynamic = "force-dynamic";

/**
 * Exchange a Firebase ID token for the 14-day httpOnly session cookie, the
 * same step AccessBuddy's /api/auth/session performs. Only allow-listed
 * emails get a cookie; everyone else gets 403 and no session.
 */
export async function POST(request: NextRequest) {
  const ip = getClientIp(request);
  const rl = await checkRateLimit(`ip:${ip}`, { namespace: "auth.session", windowSeconds: 60, max: 20 });
  if (!rl.ok) return NextResponse.json({ error: "Too many requests" }, { status: 429, headers: { "Retry-After": String(rl.retryAfter) } });

  let idToken: string;
  try {
    ({ idToken } = await request.json());
  } catch {
    return NextResponse.json({ error: "Token required" }, { status: 400 });
  }
  if (!idToken || typeof idToken !== "string") return NextResponse.json({ error: "Token required" }, { status: 400 });

  try {
    const auth = getAdminAuth();
    const decoded = await auth.verifyIdToken(idToken, true);
    const email = (decoded.email ?? "").toLowerCase().trim();
    if (!email || !decoded.email_verified) return NextResponse.json({ error: "Email not verified" }, { status: 401 });

    const member = await getMemberByEmail(email);
    if (!member) {
      return NextResponse.json({ error: "Not a member" }, { status: 403 });
    }
    await linkMemberUid(email, decoded.uid);

    const sessionValue = await auth.createSessionCookie(idToken, { expiresIn: SESSION_MAX_AGE_SECONDS * 1000 });
    const store = await cookies();
    store.set(SESSION_COOKIE_NAME, sessionValue, sessionCookieOptions);
    return NextResponse.json({ success: true, displayName: member.displayName, role: member.role }, { headers: { "Cache-Control": "no-store" } });
  } catch (err) {
    console.error("Session creation error:", err);
    return NextResponse.json({ error: "Failed to create session" }, { status: 401 });
  }
}

export async function DELETE() {
  const store = await cookies();
  store.delete(SESSION_COOKIE_NAME);
  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from "next/server";
import { getAdminAuth } from "@/lib/firebase-admin";
import { getAuthUser } from "@/lib/auth";
import { clientEnv } from "@/env";

export const dynamic = "force-dynamic";

/**
 * Mint a Firebase custom token for the holder of a valid session cookie so
 * the browser Firestore SDK can authenticate when it has no Firebase session
 * of its own (OTP sign-in, cleared site data). The claims mirror what
 * members.ts sets, so rules see `member: true` immediately.
 *
 * POST only, same-origin only, never cached.
 */
export async function POST(request: NextRequest) {
  const origin = request.headers.get("origin");
  if (!origin || origin !== new URL(clientEnv.NEXT_PUBLIC_APP_URL).origin) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }
  const user = await getAuthUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  const token = await getAdminAuth().createCustomToken(user.uid, {
    member: true,
    admin: user.role === "admin",
    name: user.displayName,
  });
  return NextResponse.json({ token }, { headers: { "Cache-Control": "no-store" } });
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { getAdminAuth } from "@/lib/firebase-admin";
import { getMemberByEmail } from "@/lib/members";
import { checkRateLimitIpAndEmail, getClientIp } from "@/lib/rate-limit";
import { sendMagicLinkEmail } from "@/lib/email";
import { safeRedirect } from "@/lib/safe-redirect";
import { clientEnv, resendConfigured } from "@/env";

export const dynamic = "force-dynamic";

const schema = z.object({ email: z.string().email(), redirect: z.string().optional() });

/**
 * Magic-link send, rate limited 10/IP and 5/email per minute as in
 * AccessBuddy. With Resend configured the link is generated by Firebase Admin
 * and emailed from our domain; otherwise the response asks the client to let
 * Firebase send it. Never reveals whether an email is on the member list.
 */
export async function POST(request: NextRequest) {
  const body = await request.json().catch(() => null);
  const parsed = schema.safeParse(body);
  if (!parsed.success) return NextResponse.json({ error: "Valid email required" }, { status: 400 });

  const email = parsed.data.email.toLowerCase().trim();
  const ip = getClientIp(request);
  const rl = await checkRateLimitIpAndEmail("auth.send-magic-link", ip, email, { windowSeconds: 60, maxPerIp: 10, maxPerEmail: 5 });
  if (!rl.ok) {
    return NextResponse.json({ error: "Too many requests, please wait a moment and try again." }, { status: 429, headers: { "Retry-After": String(rl.retryAfter) } });
  }

  if (!resendConfigured()) {
    // Firebase mails the link from the client. Membership is enforced at
    // /api/auth/session, so a non-member gets an email but no session.
    return NextResponse.json({ sent: true, clientSend: true });
  }

  const member = await getMemberByEmail(email);
  if (!member) return NextResponse.json({ sent: true });

  const redirect = safeRedirect(parsed.data.redirect);
  const link = await getAdminAuth().generateSignInWithEmailLink(email, {
    url: `${clientEnv.NEXT_PUBLIC_APP_URL}${clientEnv.NEXT_PUBLIC_BASE_PATH}/auth/callback?redirect=${encodeURIComponent(redirect)}`,
    handleCodeInApp: true,
  });
  const result = await sendMagicLinkEmail(email, link);
  if (!result.sent) {
    return NextResponse.json({ error: "We could not send your sign-in link right now. Please try again in a few minutes." }, { status: 502 });
  }
  return NextResponse.json({ sent: true });
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { getMemberByEmail } from "@/lib/members";
import { generateOtpCode, setOtp } from "@/lib/otp-store";
import { checkRateLimitIpAndEmail, getClientIp } from "@/lib/rate-limit";
import { sendVerificationCodeEmail } from "@/lib/email";
import { resendConfigured } from "@/env";

export const dynamic = "force-dynamic";

const schema = z.object({ email: z.string().email() });

/** Email-code send, ported from AccessBuddy. Requires a configured mailer. */
export async function POST(request: NextRequest) {
  if (!resendConfigured()) return NextResponse.json({ error: "Code sign-in is not enabled" }, { status: 404 });
  const body = await request.json().catch(() => null);
  const parsed = schema.safeParse(body);
  if (!parsed.success) return NextResponse.json({ error: "Valid email required" }, { status: 400 });

  const email = parsed.data.email.toLowerCase().trim();
  const ip = getClientIp(request);
  const rl = await checkRateLimitIpAndEmail("auth.send-otp", ip, email, { windowSeconds: 60, maxPerIp: 10, maxPerEmail: 5 });
  if (!rl.ok) {
    return NextResponse.json({ error: "Too many requests, please wait a moment and try again." }, { status: 429, headers: { "Retry-After": String(rl.retryAfter) } });
  }

  const member = await getMemberByEmail(email);
  if (!member) return NextResponse.json({ sent: true });

  const code = generateOtpCode();
  await setOtp(email, code);
  if (process.env.NODE_ENV !== "production") {
    console.log(`[DEV] Sign-in code for ${email}: ${code}`);
    return NextResponse.json({ sent: true, devCode: code });
  }
  const result = await sendVerificationCodeEmail(email, code);
  if (!result.sent) return NextResponse.json({ error: "We could not send your sign-in code right now. Please try again in a few minutes." }, { status: 502 });
  return NextResponse.json({ sent: true });
}

import { NextRequest, NextResponse } from "next/server";
import { cookies } from "next/headers";
import { z } from "zod";
import { getAdminAuth } from "@/lib/firebase-admin";
import { getMemberByEmail, linkMemberUid } from "@/lib/members";
import { verifyOtp } from "@/lib/otp-store";
import { checkRateLimitIpAndEmail, getClientIp } from "@/lib/rate-limit";
import { SESSION_COOKIE_NAME, sessionCookieOptions, signOtpSession } from "@/lib/auth";
import { resendConfigured } from "@/env";

export const dynamic = "force-dynamic";

const schema = z.object({ email: z.string().email(), code: z.string().length(6) });

/**
 * Email-code verification, ported from AccessBuddy: hashed single-use code,
 * rate limited 30/IP and 10/email per 15 minutes, HMAC-signed session.
 * Ensures a Firebase user exists for the email so the browser can later mint
 * a custom token for Firestore.
 */
export async function POST(request: NextRequest) {
  if (!resendConfigured()) return NextResponse.json({ error: "Code sign-in is not enabled" }, { status: 404 });
  const body = await request.json().catch(() => null);
  const parsed = schema.safeParse(body);
  if (!parsed.success) return NextResponse.json({ error: "Valid email and 6-digit code required" }, { status: 400 });

  const email = parsed.data.email.toLowerCase().trim();
  const ip = getClientIp(request);
  const rl = await checkRateLimitIpAndEmail("auth.verify-otp", ip, email, { windowSeconds: 15 * 60, maxPerIp: 30, maxPerEmail: 10 });
  if (!rl.ok) {
    return NextResponse.json({ error: "Too many attempts, please wait a moment and try again." }, { status: 429, headers: { "Retry-After": String(rl.retryAfter) } });
  }

  const result = await verifyOtp(email, parsed.data.code);
  if (result !== "valid") return NextResponse.json({ error: "Invalid or expired code" }, { status: 401 });

  const member = await getMemberByEmail(email);
  if (!member) return NextResponse.json({ error: "Invalid or expired code" }, { status: 401 });

  const auth = getAdminAuth();
  let uid: string;
  try {
    uid = (await auth.getUserByEmail(email)).uid;
  } catch {
    uid = (await auth.createUser({ email, emailVerified: true, displayName: member.displayName })).uid;
  }
  await linkMemberUid(email, uid);

  const store = await cookies();
  store.set(SESSION_COOKIE_NAME, signOtpSession({ uid, email }), sessionCookieOptions);
  return NextResponse.json({ success: true, displayName: member.displayName, role: member.role });
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { getAuthUser } from "@/lib/auth";
import { listMembers, removeMember, upsertMember } from "@/lib/members";

export const dynamic = "force-dynamic";

/**
 * Member allow-list administration. Members may list (for display names);
 * only admins may add, change or remove. The page's profiles() shim reads
 * display names straight from Firestore, so GET here is for ops use.
 */
export async function GET() {
  const user = await getAuthUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  const members = await listMembers();
  return NextResponse.json({ members: members.map(({ email, displayName, role, uid }) => ({ email, displayName, role, uid: uid ?? null })) });
}

const upsertSchema = z.object({ email: z.string().email(), displayName: z.string().min(1).max(80), role: z.enum(["member", "admin"]).default("member") });

export async function PUT(request: NextRequest) {
  const user = await getAuthUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  const parsed = upsertSchema.safeParse(await request.json().catch(() => null));
  if (!parsed.success) return NextResponse.json({ error: "email, displayName and role required" }, { status: 400 });
  const rec = await upsertMember(parsed.data, user.email);
  return NextResponse.json({ member: rec });
}

export async function DELETE(request: NextRequest) {
  const user = await getAuthUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  if (user.role !== "admin") return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  const email = new URL(request.url).searchParams.get("email") ?? "";
  if (!email) return NextResponse.json({ error: "email required" }, { status: 400 });
  if (email.toLowerCase().trim() === user.email) return NextResponse.json({ error: "You cannot remove yourself" }, { status: 400 });
  await removeMember(email);
  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from "next/server";
import { requireScheduler } from "@/lib/cron-auth";
import { runWeatherJob } from "@/lib/weather/job";

export const dynamic = "force-dynamic";
export const maxDuration = 120;

/** Cloud Scheduler entry point (OIDC-authenticated). */
export async function GET(request: NextRequest) {
  const unauthorised = await requireScheduler(request, "weather");
  if (unauthorised) return unauthorised;
  try {
    const summary = await runWeatherJob({ trigger: "scheduler" });
    return NextResponse.json(summary);
  } catch (err) {
    console.error("Weather job failed:", err);
    return NextResponse.json({ error: "Weather job failed", detail: String(err) }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getAuthUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { runWeatherJob } from "@/lib/weather/job";
import { clientEnv } from "@/env";

export const dynamic = "force-dynamic";
export const maxDuration = 120;

/**
 * "Refresh from BOM now" button. Session-gated, same-origin, and limited to
 * two runs a minute across all members so the BOM's FTP is not hammered.
 */
export async function POST(request: NextRequest) {
  const origin = request.headers.get("origin");
  if (!origin || origin !== new URL(clientEnv.NEXT_PUBLIC_APP_URL).origin) return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  const user = await getAuthUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  const rl = await checkRateLimit("global", { namespace: "weather.refresh", windowSeconds: 60, max: 2 });
  if (!rl.ok) return NextResponse.json({ error: "A refresh ran a moment ago. Try again shortly." }, { status: 429, headers: { "Retry-After": String(rl.retryAfter) } });
  try {
    const summary = await runWeatherJob({ trigger: `manual:${user.email}` });
    return NextResponse.json(summary, { headers: { "Cache-Control": "no-store" } });
  } catch (err) {
    console.error("Manual weather refresh failed:", err);
    return NextResponse.json({ error: "BOM refresh failed", detail: String(err) }, { status: 502 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { randomBytes } from "node:crypto";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { firstName, getAuthUser } from "@/lib/auth";
import { clientEnv } from "@/env";

export const dynamic = "force-dynamic";

/**
 * Serves the Operational Service Summary page at the basePath root.
 *
 * The page is the built artifact (oss/index.html) with three injections made
 * at request time: a per-request nonce on every script tag, the signed-in
 * member's name and logout URL for the chooser, and the Firebase config and
 * bridge script that replaces claude.ai storage. Signed-out requests go to
 * sign-in; no page bytes leave the server without a session.
 */
let cachedHtml: string | null = null;
function loadPage(): string {
  if (cachedHtml && process.env.NODE_ENV === "production") return cachedHtml;
  cachedHtml = readFileSync(resolve(process.cwd(), "oss/index.html"), "utf8");
  return cachedHtml;
}

export async function GET(request: NextRequest) {
  const user = await getAuthUser();
  const base = clientEnv.NEXT_PUBLIC_BASE_PATH;
  if (!user) {
    const to = new URL(`${base}/sign-in`, clientEnv.NEXT_PUBLIC_APP_URL);
    const wanted = request.nextUrl.hash ? `/${request.nextUrl.hash}` : "/";
    to.searchParams.set("redirect", wanted);
    return NextResponse.redirect(to, { status: 303 });
  }

  const nonce = randomBytes(16).toString("base64");
  const bootstrap = {
    firebase: {
      apiKey: clientEnv.NEXT_PUBLIC_FIREBASE_API_KEY,
      authDomain: clientEnv.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
      projectId: clientEnv.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
      appId: clientEnv.NEXT_PUBLIC_FIREBASE_APP_ID,
    },
    basePath: base,
    user: { id: user.uid, email: user.email, displayName: user.displayName, role: user.role },
  };
  const head =
    `<script nonce="${nonce}">` +
    `window.OSS_USER_NAME=${JSON.stringify(user.displayName)};` +
    `window.OSS_USER_FIRST_NAME=${JSON.stringify(firstName(user.displayName))};` +
    `window.OSS_LOGOUT_URL=${JSON.stringify(`${base}/logout`)};` +
    `window.OSS_BOOTSTRAP=${JSON.stringify(bootstrap).replace(/</g, "\\u003c")};` +
    `</script>` +
    `<script nonce="${nonce}" src="${base}/vendor/bridge.js"></script>`;

  let html = loadPage().replace(/<script\b(?![^>]*\bnonce=)/gi, `<script nonce="${nonce}"`);
  html = html.includes("</head>") ? html.replace("</head>", `${head}</head>`) : head + html;

  const csp = [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}'`,
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: blob:",
    "font-src 'self' data:",
    "connect-src 'self' https://firestore.googleapis.com https://securetoken.googleapis.com https://identitytoolkit.googleapis.com wss://firestore.googleapis.com",
    "frame-src 'none'",
    "frame-ancestors 'none'",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
  ].join("; ");

  return new NextResponse(html, {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "private, no-store",
      "Content-Security-Policy": csp,
    },
  });
}

import { NextResponse, type NextRequest } from "next/server";

/**
 * Edge gate: anything under the app that is not an auth surface needs a
 * session cookie to exist. The cookie is verified properly in getAuthUser();
 * this just stops anonymous requests from reaching data or page handlers at
 * all, including the static vendor files that only signed-in pages load.
 */
const PUBLIC_PREFIXES = ["/sign-in", "/auth/", "/not-a-member", "/logout", "/api/auth/", "/api/health", "/api/cron/", "/_next/", "/favicon"];

export function middleware(request: NextRequest) {
  const path = request.nextUrl.pathname.replace(/^\/lsv\/dailysummary/, "") || "/";
  if (PUBLIC_PREFIXES.some((p) => path.startsWith(p))) return NextResponse.next();
  if (request.cookies.get("session")?.value) return NextResponse.next();
  if (path.startsWith("/api/")) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const signIn = request.nextUrl.clone();
  signIn.pathname = "/sign-in";
  signIn.search = "";
  return NextResponse.redirect(signIn, { status: 303 });
}

export const config = {
  matcher: ["/((?!_next/static|_next/image).*)"],
};

