"""Apply the hosting changes to the pack's source parts. Every replacement is asserted."""
import sys, pathlib

ux = pathlib.Path(sys.argv[1])

def patch(name, pairs):
    p = ux / name
    s = p.read_text()
    for a, b in pairs:
        assert a in s, f"{name}: anchor not found: {a[:70]!r}"
        assert s.count(a) == 1, f"{name}: anchor not unique: {a[:70]!r}"
        s = s.replace(a, b)
    p.write_text(s)
    print("patched", name, len(pairs))

# --- build.py: vendored libraries instead of the CDN (strict CSP on the host) ---
V = "/lsv/dailysummary/vendor"
patch("build.py", [(
    r"""'<script src="https://cdn.jsdelivr.net/npm/docx@8.5.0/build/index.umd.js"></script>\n<script src="https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js"></script>\n<script src="https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js"></script>')""",
    rf"""'<script src="{V}/docx.min.js"></script>\n<script src="{V}/xlsx.full.min.js"></script>\n<script src="{V}/jszip.min.js"></script>')
assert 'cdn.jsdelivr.net' not in head  # docx@8.5.0, xlsx@0.18.5, jszip@3.10.1 are vendored by `bun run vendor`""",
)])

# --- markup.html: Refresh from BOM now ---
patch("markup.html", [(
    """<button class="btn primary" id="w-bomtoggle" aria-expanded="false">Fill from BOM</button>""",
    """<button class="btn" id="w-refresh" type="button" hidden title="Fetch the latest Bureau forecast now. Values typed by a member are kept.">Refresh from BOM now</button>
      <button class="btn primary" id="w-bomtoggle" aria-expanded="false">Fill from BOM</button>""",
)])

# --- views.js: per-value manual tracking in the weather sheet ---
patch("views.js", [
    (
        """const wxTimers = {};
function saveWeatherDay(d, source) {
  clearTimeout(wxTimers[d]);
  wxTimers[d] = setTimeout(async () => {
    const regions = { ...(S.weather[d]?.regions || {}) };""",
        """const wxTimers = {};
/* Which cells a member typed by hand: weather/<date>.manual is a list of "Area|field" keys. The scheduled BOM job
   never overwrites those; clearing a cell, or filling it from the BOM, hands it back to the BOM. */
const wxManual = {};
function markManual(d, r, k, on) { const m = (wxManual[d] ||= { add: new Set(), del: new Set() }); const key = r + "|" + k; (on ? m.add : m.del).add(key); (on ? m.del : m.add).delete(key); }
function manualKeys(w) {
  if (!w) return []; if (Array.isArray(w.manual)) return w.manual;
  if (/^BOM forecast issued/.test(w.source || "")) return [];
  // Days saved before tracking existed: treat every filled value as typed by a member.
  return Object.entries(w.regions || {}).flatMap(([r, rec]) => Object.entries(rec || {}).filter(([k, v]) => k !== "fire" && v != null && v !== "").map(([k]) => r + "|" + k));
}
function saveWeatherDay(d, source) {
  clearTimeout(wxTimers[d]);
  wxTimers[d] = setTimeout(async () => {
    const pend = wxManual[d] || { add: new Set(), del: new Set() }; delete wxManual[d];
    const manual = [...new Set([...manualKeys(S.weather[d]), ...pend.add])].filter(x => !pend.del.has(x)).sort();
    const regions = { ...(S.weather[d]?.regions || {}) };""",
    ),
    (
        """    S.weather[d] = { ...(S.weather[d] || {}), date: d, regions };""",
        """    S.weather[d] = { ...(S.weather[d] || {}), date: d, regions, manual };""",
    ),
