/**
 * The one custom claim this app issues and reads.
 *
 * It is scoped to the app (`poc_oss`, app id `oss`) instead of a bare
 * `member` / `admin` flag, so that in a sign-in pool shared with other LSV
 * apps a member of some other app carries no access here. Value: the member's
 * role. Firestore rules, the custom-token mint, the browser bridge and the
 * probes all read this name; change it in every one of them together.
 */
export const APP_CLAIM = "poc_oss" as const;
export type AppRole = "member" | "admin";

/** The complete custom-claims object for a member. Setting it replaces any older claims on the user. */
export function memberClaims(role: AppRole, displayName: string): Record<string, unknown> {
  return { [APP_CLAIM]: role, name: displayName };
}

/** Claims for someone who is no longer a member: nothing. */
export function noClaims(): Record<string, unknown> {
  return {};
}

export function roleFromClaims(claims: Record<string, unknown> | undefined | null): AppRole | null {
  const v = claims?.[APP_CLAIM];
  return v === "member" || v === "admin" ? v : null;
}
