#!/usr/bin/env bun
/**
 * Re-issue sign-in claims from the member allow-list.
 *
 *   bun run scripts/resync-claims.ts [--dry-run]
 *
 * For every Firebase user: a current member gets exactly the app-scoped claim
 * ({ poc_oss: role, name }); anyone else has all custom claims removed. The
 * claims object is replaced, not merged, so claims issued by older versions
 * (bare `member` / `admin`) are deleted from the user record, not just ignored.
 * Sessions are left alone: a signed-in member's next token refresh picks up
 * the new claim, so nobody is signed out.
 */
import { initializeApp, applicationDefault } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";
import { getFirestore } from "firebase-admin/firestore";
import { memberClaims, noClaims } from "../src/lib/claims";

const projectId = process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID ?? process.env.GOOGLE_CLOUD_PROJECT ?? "lsv-oss-prod";
const dry = process.argv.includes("--dry-run");
initializeApp({ credential: applicationDefault(), projectId });
const auth = getAuth();
const members = new Map<string, { role: "member" | "admin"; displayName: string }>();
for (const d of (await getFirestore().collection("members").get()).docs) {
  const m = d.data() as { email: string; role: "member" | "admin"; displayName: string };
  members.set(d.id, { role: m.role, displayName: m.displayName });
}
const same = (a: unknown, b: unknown) => JSON.stringify(a ?? {}, Object.keys((a ?? {}) as object).sort()) === JSON.stringify(b ?? {}, Object.keys((b ?? {}) as object).sort());
let set = 0, cleared = 0, unchanged = 0, users = 0;
let pageToken: string | undefined;
do {
  const page = await auth.listUsers(1000, pageToken);
  for (const u of page.users) {
    users++;
    const m = u.email ? members.get(u.email.toLowerCase()) : undefined;
    const want = m ? memberClaims(m.role, m.displayName) : noClaims();
    if (same(u.customClaims, want)) { unchanged++; continue; }
    console.log(`${dry ? "would set" : "set"} ${u.uid} ${m ? `member(${m.role})` : "non-member"}: ${JSON.stringify(u.customClaims ?? {})} -> ${JSON.stringify(want)}`);
    if (!dry) await auth.setCustomUserClaims(u.uid, want);
    if (m) set++; else cleared++;
  }
  pageToken = page.pageToken;
} while (pageToken);
console.log(`resync ${dry ? "(dry run) " : ""}complete: ${users} users, ${set} members updated, ${cleared} non-members cleared, ${unchanged} unchanged`);
