import { appDb, firestoreOverrideReader, FirestoreRateLimitStore, verifyIdToken } from "@lsv-poc/poc-auth/firebase";

/**
 * Production wiring for the Service Summary as an LSV POC platform tenant
 * (app id `oss`), built lazily so `next build` needs no credentials.
 *
 * Sign-in contract (vendor/poc-auth): the hub is the only writer of sign-in
 * claims. This app verifies the ID token with Google's public keys, reads
 * `poc_oss` from it, and signs its own `__session` cookie. Revokes and
 * downgrades arrive as `platformAccess/<uid>` written by the hub into this
 * app's database. Nothing here calls Firebase Auth admin.
 */
export const appId = process.env.APP_ID ?? "oss";
export const APP_NAME = "Operational Service Summary";
export const APP_CLAIM = appClaimName(appId);
export const log = createLogger(appId);
export const origin = () => process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";
export const secureCookie = () => process.env.NODE_ENV === "production";
const secret = () => process.env.SESSION_SIGNING_SECRET ?? "";

export const db = () => appDb();

let _gate: ReturnType<typeof createAccessGate> | null = null;
export function gate() {
  _gate ??= createAccessGate({ appId, secret, readOverride: firestoreOverrideReader(() => appDb()) });
  return _gate;
}

let _limiter: ReturnType<typeof createRateLimiter> | null = null;
export function rateLimiter() {
  _limiter ??= createRateLimiter(new FirestoreRateLimitStore(() => appDb()));
  return _limiter;
}

/** "nicholas.h.wood@example.com" → "Nicholas H Wood", for members whose account has no display name. */
export function nameFromEmail(email: string): string {
  return email
    .split("@")[0]
    .split(/[._-]+/)
    .filter(Boolean)
    .map((p) => p[0].toUpperCase() + p.slice(1))
    .join(" ");
}

export type Profile = { name: string; email: string };

/**
 * profiles/<uid>: the display name the page shows beside "updated by". It
 * replaces the old members/ allow-list as the source of names; access itself
 * is the hub's. Written by the server at sign-in, read-only to members.
 */
async function recordProfile(decoded: DecodedIdToken): Promise<void> {
  const email = (decoded.email ?? "").toLowerCase().trim();
  const name = typeof decoded.name === "string" && decoded.name.trim() ? decoded.name.trim() : nameFromEmail(email);
  await appDb().collection("profiles").doc(decoded.uid).set({ name, email, lastSignInAt: new Date().toISOString() }, { merge: true });
}

export async function readProfile(uid: string, email: string): Promise<Profile> {
  try {
    const snap = await appDb().collection("profiles").doc(uid).get();
    const d = snap.data() as Partial<Profile> | undefined;
    if (d?.name) return { name: d.name, email: d.email ?? email };
  } catch (err) {
    log.warn("profile read failed", { err, uid });
  }
  return { name: nameFromEmail(email), email };
}

let _exchange: ReturnType<typeof createSessionExchange> | null = null;
export function sessionExchange() {
  _exchange ??= createSessionExchange({
    appId,
    secret,
    verifyIdToken,
    rateLimiter: rateLimiter(),
    log,
    secureCookie: secureCookie(),
    async authorise(decoded): Promise<AppRole | null> {
      const role = roleFromClaims(decoded, appId);
      if (role) await recordProfile(decoded).catch((err) => log.warn("profile write failed", { err, uid: decoded.uid }));
      return role;
    },
  });
  return _exchange;
}

export const sameOrigin = (request: Request) => request.headers.get("origin") === new URL(origin()).origin;
export const json = (status: number, body: unknown, headers: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", "Cache-Control": "private, no-store", ...headers } });
