import { createRemoteJWKSet, jwtVerify } from "jose";
import { json, log } from "@/lib/deps";
import { jobs } from "@/jobs";

export const dynamic = "force-dynamic";
export const maxDuration = 60;

const GOOGLE_JWKS = createRemoteJWKSet(new URL("https://www.googleapis.com/oauth2/v3/certs"));

/**
 * Cloud Scheduler target (infra/modules/poc-app `scheduled_jobs`). The
 * service is publicly invokable, so the route checks the scheduler's
 * Google-signed OIDC token itself: issuer Google, email the scheduler
 * account named in JOB_INVOKER. A failure logs event job.failed, which the
 * module's job-failure alert counts. Same shape as the platform host template.
 */
export async function POST(request: Request, ctx: { params: Promise<{ name: string }> }) {
  const { name } = await ctx.params;
  const invoker = process.env.JOB_INVOKER;
  const token = request.headers.get("authorization")?.replace(/^Bearer /, "");
  if (!invoker || !token) return json(401, { error: "Unauthorized" });
  try {
    const { payload } = await jwtVerify(token, GOOGLE_JWKS, { issuer: ["https://accounts.google.com", "accounts.google.com"] });
    if (payload.email !== invoker || payload.email_verified !== true) throw new Error("wrong invoker");
  } catch {
    return json(401, { error: "Unauthorized" });
  }
  const job = jobs[name];
  if (!job) return json(404, { error: "No such job" });
  try {
    const result = await job();
    log.info("job done", { event: "job.done", job: name });
    return json(200, { ok: true, result });
  } catch (err) {
    log.error("job failed", { event: "job.failed", job: name, err });
    return json(500, { error: "Job failed" });
  }
}
