/**
 * Shared by the probes: mint Firebase ID tokens without email, as the
 * platform owner. Custom tokens are signed through IAM signBlob as
 * PROBE_SIGNER (a service account the caller holds
 * roles/iam.serviceAccountTokenCreator on, e.g. oss-run@lsv-poc...).
 * The browser API key only answers requests carrying a Referer of a `poc`
 * hostname, so every sign-in call sends the app URL as Referer.
 */
import { applicationDefault, initializeApp } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";

export const APP_URL = (process.env.APP_URL ?? "").replace(/\/$/, "");
export const PROJECT = process.env.FIREBASE_PROJECT_ID ?? "lsv-poc";
export const DATABASE = process.env.FIRESTORE_DATABASE ?? "poc-oss";
export const API_KEY = process.env.NEXT_PUBLIC_FIREBASE_API_KEY ?? "";
const signer = process.env.PROBE_SIGNER ?? `oss-run@${PROJECT}.iam.gserviceaccount.com`;
if (!APP_URL || !API_KEY) throw new Error("APP_URL and NEXT_PUBLIC_FIREBASE_API_KEY are required");

initializeApp({ credential: applicationDefault(), projectId: PROJECT, serviceAccountId: signer });
export const adminAuth = getAuth();

let failed = 0;
let total = 0;
export function check(name: string, ok: boolean, detail = "") {
  total++;
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? `  (${detail})` : ""}`);
}
export function finish(): never {
  console.log(`${total - failed}/${total} passed`);
  process.exit(failed ? 1 : 0);
}

/** ID token for a uid, optionally with extra developer claims on the custom token. */
export async function idTokenForUid(uid: string, claims?: Record<string, unknown>): Promise<string> {
  const custom = await adminAuth.createCustomToken(uid, claims);
  const r = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signInWithCustomToken?key=${API_KEY}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Referer: `${APP_URL}/` },
    body: JSON.stringify({ token: custom, returnSecureToken: true }),
  });
  const b = (await r.json()) as { idToken?: string; error?: { message?: string } };
  if (!b.idToken) throw new Error(`custom token exchange failed: ${b.error?.message ?? r.status}`);
  return b.idToken;
}

/** ID token for an existing account (its own hub-issued claims apply). */
export async function idTokenForEmail(email: string): Promise<{ idToken: string; uid: string }> {
  const u = await adminAuth.getUserByEmail(email.toLowerCase());
  return { idToken: await idTokenForUid(u.uid), uid: u.uid };
}

export const exchange = (idToken: string) =>
  fetch(`${APP_URL}/api/auth/session`, { method: "POST", headers: { "Content-Type": "application/json", Origin: APP_URL }, body: JSON.stringify({ idToken }) });

export const cookieFrom = (res: Response) => (res.headers.get("set-cookie") ?? "").split(";")[0];
EOF
