#!/usr/bin/env bun
/**
 * HTTP end-to-end probe of the deployed Service Summary, without email.
 *
 *   APP_URL=https://service-summary.poc.nicholaswood.com.au NEXT_PUBLIC_FIREBASE_API_KEY=<key> \
 *     bun run probe <allocated-email> <unallocated-email>
 *
 * Run as the platform owner (see scripts/lib-probe.ts). Checks: signed-out
 * refusals on page, data and script files; an account the hub has not
 * allocated gets 403 and no cookie; an allocated member gets the page with a
 * per-request nonce policy, the injected chooser hooks, and a working token
 * mint; tampered cookies and cross-origin posts are refused.
 */
import { APP_URL, check, cookieFrom, exchange, finish, idTokenForEmail } from "./lib-probe";

const [member, outsider] = process.argv.slice(2);
if (!member || !outsider) throw new Error("usage: probe <allocated-email> <unallocated-email>");

console.log(`# Signed out: ${APP_URL}`);
const anon = await fetch(`${APP_URL}/`, { redirect: "manual" });
check("GET / → 303 to /sign-in", anon.status === 303 && (anon.headers.get("location") ?? "") === `${APP_URL}/sign-in`, `${anon.status} ${anon.headers.get("location")}`);
const health = await fetch(`${APP_URL}/api/health`);
const hb = (await health.json()) as { ok?: boolean; app?: string; version?: string };
check("GET /api/health → 200, app oss", health.status === 200 && hb.ok === true && hb.app === "oss", JSON.stringify(hb));
check("GET /sign-in → 200", (await fetch(`${APP_URL}/sign-in`)).status === 200);
for (const p of ["/vendor/bridge.js", "/vendor/jszip.min.js"]) {
  const r = await fetch(`${APP_URL}${p}`, { redirect: "manual" });
  check(`GET ${p} refused without a session`, r.status === 303, String(r.status));
}
check("POST /api/weather/refresh → 401", (await fetch(`${APP_URL}/api/weather/refresh`, { method: "POST", headers: { Origin: APP_URL } })).status === 401);
check("POST /api/auth/firebase-token → 401", (await fetch(`${APP_URL}/api/auth/firebase-token`, { method: "POST", headers: { Origin: APP_URL } })).status === 401);
check("POST /api/jobs/weather without a scheduler token → 401", (await fetch(`${APP_URL}/api/jobs/weather`, { method: "POST" })).status === 401);
check("POST /api/jobs/weather with a junk token → 401", (await fetch(`${APP_URL}/api/jobs/weather`, { method: "POST", headers: { Authorization: "Bearer not.a.token" } })).status === 401);
for (const gone of ["/api/members", "/lsv/dailysummary", "/not-a-member"]) {
  const r = await fetch(`${APP_URL}${gone}`, { redirect: "manual" });
  check(`old surface ${gone} serves nothing`, r.status === 401 || r.status === 303 || r.status === 404, String(r.status));
}

console.log(`\n# Not allocated in the hub: ${outsider}`);
const o = await exchange((await idTokenForEmail(outsider)).idToken);
check("session exchange → 403 and no cookie", o.status === 403 && !o.headers.get("set-cookie"), String(o.status));

console.log(`\n# Allocated: ${member}`);
const s = await exchange((await idTokenForEmail(member)).idToken);
const setCookie = s.headers.get("set-cookie") ?? "";
const cookie = cookieFrom(s);
check("session exchange → 200", s.status === 200, `${s.status} ${await s.clone().text()}`);
check("cookie __session; HttpOnly; Secure; SameSite=Lax; 14 days", cookie.startsWith("__session=") && /HttpOnly/i.test(setCookie) && /Secure/i.test(setCookie) && /SameSite=Lax/i.test(setCookie) && /Max-Age=1209600/.test(setCookie), setCookie.replace(/__session=[^;]+/, "__session=<redacted>"));

const page = await fetch(`${APP_URL}/`, { headers: { Cookie: cookie }, redirect: "manual" });
const html = await page.text();
const csp = page.headers.get("content-security-policy") ?? "";
check("GET / → 200 text/html, no-store", page.status === 200 && (page.headers.get("content-type") ?? "").startsWith("text/html") && (page.headers.get("cache-control") ?? "").includes("no-store"), String(page.status));
check("chooser hooks injected", html.includes("window.OSS_USER_NAME=") && html.includes('window.OSS_LOGOUT_URL="/sign-out"'));
check("bootstrap names the app database and claim", html.includes('"database":"poc-oss"') && html.includes('"claim":"poc_oss"'));
const nonce = csp.match(/'nonce-([^']+)'/)?.[1];
const bare = (html.match(/<script\b[^>]*>/gi) ?? []).filter((t) => !t.includes(`nonce="${nonce}"`));
check("every script tag carries the per-request nonce", !!nonce && bare.length === 0, `${bare.length} without`);
const external = csp.split(";").flatMap((d) => d.trim().split(/\s+/).slice(1)).filter((x) => /^(https?|wss?):/.test(x));
check("CSP reaches only Firebase sign-in and Firestore", external.length > 0 && external.every((x) => /^(https|wss):\/\/(firestore|securetoken|identitytoolkit)\.googleapis\.com$/.test(x)), external.join(" "));
check("no library loads from a CDN", !/cdn\.jsdelivr|unpkg\.com|cdnjs/.test(html));
check("security headers", page.headers.get("x-frame-options") === "DENY" && page.headers.get("x-content-type-options") === "nosniff" && (page.headers.get("strict-transport-security") ?? "").includes("max-age"));
check("vendored script served to a member", (await fetch(`${APP_URL}/vendor/bridge.js`, { headers: { Cookie: cookie } })).status === 200);

const mintGet = await fetch(`${APP_URL}/api/auth/firebase-token`, { headers: { Cookie: cookie } });
check("token mint GET → 405", mintGet.status === 405, String(mintGet.status));
check("token mint from another origin → 403", (await fetch(`${APP_URL}/api/auth/firebase-token`, { method: "POST", headers: { Cookie: cookie, Origin: "https://evil.example" } })).status === 403);
const mint = await fetch(`${APP_URL}/api/auth/firebase-token`, { method: "POST", headers: { Cookie: cookie, Origin: APP_URL } });
const mb = (await mint.json().catch(() => ({}))) as { token?: string };
check("token mint → 200, no-store", mint.status === 200 && !!mb.token && (mint.headers.get("cache-control") ?? "").includes("no-store"), String(mint.status));
if (mb.token) {
  const claims = (JSON.parse(Buffer.from(mb.token.split(".")[1], "base64url").toString()) as { claims?: Record<string, unknown> }).claims ?? {};
  check("minted token carries only the app-scoped claim", ["member", "admin"].includes(String(claims.poc_oss)) && Object.keys(claims).length === 1, JSON.stringify(claims));
}
check("weather refresh from another origin → 403", (await fetch(`${APP_URL}/api/weather/refresh`, { method: "POST", headers: { Cookie: cookie, Origin: "https://evil.example" } })).status === 403);

const tampered = await fetch(`${APP_URL}/`, { headers: { Cookie: cookie.slice(0, -4) + "AAAA" }, redirect: "manual" });
check("tampered cookie → back to sign-in", tampered.status === 303, String(tampered.status));
const out = await fetch(`${APP_URL}/api/auth/session`, { method: "DELETE", headers: { Cookie: cookie } });
check("sign-out clears the cookie", out.status === 200 && /__session=;.*Max-Age=0/i.test(out.headers.get("set-cookie") ?? ""), out.headers.get("set-cookie") ?? "");
finish();
EOF
