#!/usr/bin/env bun
/**
 * Export the app's documents from a Firestore database to a data file, the
 * same format Settings → Download data file produces and `seed` reads.
 *
 *   bun run scripts/export-data.ts <out.json> --project <id> [--database "(default)"]
 *
 * Used to move the data between projects: export from the old database, then
 * `bun run seed <out.json> --replace` into the new one. Only the six app
 * collections are read, so sign-in records (members, otpCodes,
 * rateLimitBuckets, platformAccess, profiles) never travel, and
 * config/weatherStatus is left for the job to recreate. Refuses any value
 * that would not survive JSON (Timestamps, references, bytes).
 */
import { writeFileSync } from "node:fs";
import { initializeApp, applicationDefault } from "firebase-admin/app";
import { getFirestore } from "firebase-admin/firestore";

const APP_COLLECTIONS = ["units", "events", "weather", "confirmations", "summaries", "config"];
const arg = (f: string) => (process.argv.indexOf(f) >= 0 ? process.argv[process.argv.indexOf(f) + 1] : undefined);
const out = process.argv[2];
const projectId = arg("--project");
const databaseId = arg("--database") ?? "(default)";
if (!out || out.startsWith("--") || !projectId) {
  console.error('usage: bun run scripts/export-data.ts <out.json> --project <id> [--database "(default)"]');
  process.exit(2);
}
initializeApp({ credential: applicationDefault(), projectId });
const db = getFirestore(databaseId);

function assertPlain(v: unknown, path: string): void {
  if (v === null || ["string", "number", "boolean"].includes(typeof v)) return;
  if (Array.isArray(v)) return v.forEach((x, i) => assertPlain(x, `${path}[${i}]`));
  if (typeof v === "object" && Object.getPrototypeOf(v) === Object.prototype) return Object.entries(v as object).forEach(([k, x]) => assertPlain(x, `${path}.${k}`));
  throw new Error(`${path} holds a ${(v as object)?.constructor?.name ?? typeof v}, which a data file cannot carry`);
}

const docs: Record<string, unknown> = {};
const counts: Record<string, number> = {};
for (const col of APP_COLLECTIONS) {
  const snap = await db.collection(col).get();
  for (const d of snap.docs) {
    if (col === "config" && d.id === "weatherStatus") continue;
    const data = d.data();
    assertPlain(data, `${col}/${d.id}`);
    docs[`${col}/${d.id}`] = data;
    counts[col] = (counts[col] ?? 0) + 1;
  }
}
writeFileSync(out, JSON.stringify({ format: "lsv-operational-service-summary", version: 1, exportedAt: new Date().toISOString(), source: `${projectId}/${databaseId}`, docs }, null, 1));
console.log(`exported ${Object.keys(docs).length} docs from ${projectId}/${databaseId}: ${JSON.stringify(counts)} -> ${out}`);
EOF
