    await dl.saveAs(path);
    const xml = await page.evaluate(
      async (b64) => {
        // JSZip is already on the page; read the document part back out of the file just produced.
        const zip = await (window as unknown as { JSZip: { loadAsync(d: string, o: object): Promise<{ file(n: string): { async(t: string): Promise<string> } }> } }).JSZip.loadAsync(b64, { base64: true });
        return zip.file("word/document.xml").async("string");
      },
      Buffer.from(await Bun.file(path).arrayBuffer()).toString("base64")
    );
    const text = xml.replace(/<\/w:tc>/g, " | ").replace(/<\/w:tr>/g, "\n").replace(/<[^>]+>/g, "").replace(/&amp;/g, "&");
    const wx = text.split("\n").filter((l) => /Min Temp|Max Temp|Wind \(KM\/h\)|Wind Direction|Rain \(mm\)|Max UV/.test(l));
    const emptyCells = wx.flatMap((l) => l.split("|").slice(2, -1)).filter((c) => c.trim() === "").length;
    const na = (text.match(/Not available/g) ?? []).length;
    console.log(`\n# ${dl.suggestedFilename()} (${statSync(path).size} bytes): ${wx.length} weather rows, ${na} "Not available", ${emptyCells} blank weather cells`);
    console.log(wx.slice(0, 6).map((l) => "  " + l.replace(/\s+/g, " ").trim()).join("\n"));
    check(`${dl.suggestedFilename().split(" Operational")[0]}: no blank weather cells`, wx.length >= 6 && emptyCells === 0, `${emptyCells} blank`);
    check(`${dl.suggestedFilename().split(" Operational")[0]}: unpublished figures read "Not available"`, na > 0, String(na));
  }
  check("no page errors", errors.length === 0, errors.slice(0, 2).join(" | "));
} finally {
  await browser.close();
}
finish();
